typedef enum {
	REGULAR_TURN,
	HARD_REGULAR_TURN,
	GRAB_TURN,
	HARD_GRAB_TURN,
	TAILSLIDE_TURN,
	GRABSLIDE_TURN,
	HARD_TAILSLIDE_TURN,
	SNAP_TURN,
	HARD_SNAP_TURN,
	TAILCHUCK_TURN,
	REBOUND_TURN,
	LAYBACK_SLIDE_TURN,
	GOUGE_TURN,
	REVERT_CUTBACK_TURN,
	CROUCH_TURN,
	CARVE_TURN
} TurnTypeEnum;

typedef enum {
	WAVE_REGIONWOBBLE = 14
} WaveRegionEnum;

enum {
	PAD_GRAB = 201,
	PAD_LSTICK_H = 203,
	PAD_OLLIE = 205,
	PAD_SLIDE = 206,
	PAD_CARVE = 209
};

typedef struct TurnPropertiesStruct {
	float maxLeanAngle;
	float maxTurnAngle;
} TurnPropertiesType;

class SurfBoardObjectClass {
	char padding0[48];
	TurnPropertiesType turnProps[21];
	float maxLeanAngle;
	float maxTurnAngle;
	char padding1[2436];
	int current_region;
	char padding2[28];
	TurnTypeEnum TurnType;

public:
	int GetWaveRegion() { return current_region; }
	int DoingFaceTurn();
	void SetTurnType(TurnTypeEnum turn)
	{
		TurnType = turn;
		maxLeanAngle = turnProps[turn].maxLeanAngle;
		maxTurnAngle = turnProps[turn].maxTurnAngle;
	}
};

class kellyslater_controller {
	char padding0[892];
	SurfBoardObjectClass my_board_controller;
	char padding1[2196];
	int turnType;
	int lastTurnType;
	int changeTurnType;
	char padding2[12];
	int last_region;
	int current_region;
	char padding3[848];
	int perform_snap;

public:
	float CtrlEvent(int control);
	int CtrlDelta(int control);
	void TurnType();
};

asm(".equ CtrlEvent__22kellyslater_controlleri,0x0020CFA0");
asm(".equ CtrlDelta__22kellyslater_controlleri,0x0020CFC8");
asm(".equ DoingFaceTurn__20SurfBoardObjectClass,0x001EFC10");

#define TRUE 1
#define FALSE 0

void kellyslater_controller::TurnType()
{
	lastTurnType = turnType;
	last_region = current_region;
	current_region = my_board_controller.GetWaveRegion();
	//turnType = (int) GetStick(PAD_LSTICK_H);

	if (CtrlEvent(PAD_GRAB) && (CtrlDelta(PAD_SLIDE) || (CtrlEvent(PAD_LSTICK_H) && CtrlEvent(PAD_SLIDE))))
		turnType = GRABSLIDE_TURN;
	else if (CtrlEvent(PAD_GRAB))
		turnType = GRAB_TURN;
	else if (CtrlDelta(PAD_OLLIE) || (CtrlEvent(PAD_LSTICK_H) && CtrlEvent(PAD_OLLIE)))
		turnType = CROUCH_TURN;
	//else if (my_board_controller.InSnapRegion() && perform_snap && CtrlEvent(PAD_SNAP))
	else if (perform_snap)
		turnType = SNAP_TURN;
	else if (CtrlDelta(PAD_CARVE) || (CtrlEvent(PAD_LSTICK_H) && CtrlEvent(PAD_CARVE)))
		turnType = CARVE_TURN;
	else if (CtrlDelta(PAD_SLIDE) || (CtrlEvent(PAD_LSTICK_H) && CtrlEvent(PAD_SLIDE)))
		turnType = TAILSLIDE_TURN;
	else if (CtrlEvent(PAD_LSTICK_H))
	{
		//if (CtrlEvent(PAD_HARD))
			//turnType = HARD_REGULAR_TURN;
		turnType = HARD_REGULAR_TURN;
		//else
			//turnType = REGULAR_TURN;
	}

	perform_snap = false;

	if (turnType != lastTurnType ||
		((last_region == WAVE_REGIONWOBBLE && current_region != WAVE_REGIONWOBBLE) && !my_board_controller.DoingFaceTurn()
			&& (turnType != TAILSLIDE_TURN) && (turnType != GRABSLIDE_TURN)))
	{
		my_board_controller.SetTurnType(REGULAR_TURN);
		changeTurnType = TRUE;
	}
	else
		changeTurnType = FALSE;

	return;
}
